// dsh-skill-manager-ytxue host half: 设置面板的 HTTP 后端 + 初次启用规范审计
// - 挂载 webServer prefix route: /api/skill-manager-ytxue
// - apply 时（初次启用/每次启用）审计 skills 目录并自动修复不合规项，写日志 ~/.dsh/skill-manager-ytxue.log
// - 零第三方 import（仅 node: 内置 + 本地 core.js）：所有 DSH 服务（webServer/sessions/
//   workspaceRegistry/settings）均为 cordis 注入，插件可放置于任意目录（含 ~/.dsh/plugins）
import { appendFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";
import { auditSkills, disableSkill, enableSkill, findProjectRoot, importPath, listDir, state } from "./core.js";

const name = "skill-manager-ytxue";
const inject = ["webServer", "workspaceRegistry", "sessions", "settings"];
/**
 * DSH 通用配置命名空间：settings.yaml 顶层键 `skill-manager-ytxue:`（与 ui-onboarding 等同构）。
 * SettingsSchema 用普通函数替代 schemastery：dsh-settings 的 resolve 以 `schema(merged)` 调用，
 * 返回 { projectRoots }；附加 toJSON 供配置表面 describe 使用（避免引入 schemastery 依赖）。
 */
const NS = "skill-manager-ytxue";
const SettingsSchema = Object.assign(
  (merged) => ({
    projectRoots: Array.isArray(merged && merged.projectRoots) ? merged.projectRoots : [],
  }),
  {
    toJSON() {
      return { type: "object", properties: { projectRoots: { type: "array", items: { type: "string" } } } };
    },
  }
);

/** DSH home 解析：$DSH_HOME 优先，否则 ~/.dsh（替代 @deepseek-ai/dsh-home-paths）。 */
function resolveDshHome() {
  return process.env.DSH_HOME || join(homedir(), ".dsh");
}

/**
 * 配置项目根（DSH 通用方式）：settings 命名空间（settings.yaml 顶层 `skill-manager-ytxue:`）为主，
 * cordis Config.projectRoots 兜底（旧配置兼容），去重合并。
 */
function configuredRoots(scope, config) {
  const fromSettings = (scope && scope.get && scope.get()) || {};
  const s = (fromSettings.projectRoots || []).filter(Boolean);
  const c = ((config && config.projectRoots) || []).filter(Boolean);
  const seen = new Set();
  return [...s, ...c].filter((p) => (seen.has(p) ? false : (seen.add(p), true)));
}

/**
 * 解析项目根：默认只显示"当前项目"。
 * 优先级：
 *   1) explicitCwd（前端传入的当前会话 cwd——切换会话即同步，最准确）；
 *   2) 最近活跃的主会话（session/event 追踪，非 subagent、有 cwd）；
 *   3) createdAt 最大的主会话 cwd；
 *   4) workspace 注册表第一个目录。
 * 向上找 .git 祖先（与 skill-filesystem 判定一致）；排除 dshHome 自身；config.projectRoots 显式补充。
 * 返回 { roots, currentRoot }。
 */
function resolveProjectRoots(ctx, config, dshHome, recentActivity, explicitCwd, settingsScope) {
  const configured = configuredRoots(settingsScope, config).filter((p) => p && p !== dshHome);
  let currentRoot = "";
  if (explicitCwd && explicitCwd !== dshHome) {
    const root = findProjectRoot(explicitCwd);
    if (root && root !== dshHome) currentRoot = root;
  }
  if (!currentRoot) {
    try {
      let best = null; // { session, ts }
      let newest = null;
      for (const s of ctx.sessions.list()) {
        const h = s && s.header;
        if (!h || !h.cwd || h.origin === "subagent") continue;
        if (!newest || h.createdAt > newest.header.createdAt) newest = s;
        const ts = recentActivity.get(s.id);
        if (ts && (!best || ts > best.ts)) best = { session: s, ts };
      }
      const chosen = best ? best.session : newest;
      if (chosen && chosen.header.cwd) currentRoot = findProjectRoot(chosen.header.cwd);
    } catch {
      /* 会话服务不可用时跳过 */
    }
  }
  if (!currentRoot) {
    try {
      const ws = ctx.workspaceRegistry.list();
      if (ws && ws.length && ws[0].path) currentRoot = ws[0].path;
    } catch {
      /* 注册表不可用时跳过 */
    }
  }
  if (currentRoot === dshHome) currentRoot = "";
  const roots = [];
  if (currentRoot) roots.push(currentRoot);
  for (const r of configured) {
    if (r !== currentRoot) roots.push(r);
  }
  return { roots, currentRoot };
}

function makeLog(dshHome) {
  const file = join(dshHome, "skill-manager-ytxue.log");
  return async (event, detail) => {
    try {
      await appendFile(file, JSON.stringify({ ts: new Date().toISOString(), event, detail }) + "\n", "utf8");
    } catch {
      /* 日志失败不阻塞主流程 */
    }
  };
}

function readBody(req, limit = 1 << 20) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (c) => {
      size += c.length;
      if (size > limit) {
        reject(new Error("body too large"));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => {
      try {
        const raw = Buffer.concat(chunks).toString("utf8");
        resolve(raw ? JSON.parse(raw) : {});
      } catch (e) {
        reject(new Error(`invalid JSON body: ${e.message}`));
      }
    });
    req.on("error", reject);
  });
}

function json(res, code, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(code, { "content-type": "application/json; charset=utf-8", "content-length": Buffer.byteLength(body) });
  res.end(body);
}

function run(res, p) {
  p.then((r) => json(res, r.ok === false ? 400 : 200, r)).catch((e) => {
    try {
      json(res, 500, { ok: false, error: String(e && e.message ? e.message : e) });
    } catch {
      /* response already closed */
    }
  });
}

/** 初次启用审计：只检查未检查（红点）的 skill，已检查（绿点）的跳过；自动修复 + 日志。 */
async function initialAudit(dshHome, log) {
  log("plugin-start", `dsh-skill-manager-ytxue 启用，开始 skill 规范审计（仅未检查项）`);
  try {
    const result = await auditSkills(dshHome, log, { onlyUnchecked: true });
    for (const f of result.fixed) {
      log("audit-fix", `${f.name}: ${f.code} ${f.detail}`);
    }
    return result;
  } catch (e) {
    log("audit-error", String(e && e.message ? e.message : e));
    return { checked: [], fixed: [], skipped: [], error: String(e && e.message ? e.message : e) };
  }
}

function apply(ctx, config) {
  const dshHome = resolveDshHome();
  const log = makeLog(dshHome);
  // DSH 通用配置：注册 settings 命名空间 `skill-manager-ytxue`（settings.yaml 顶层键）
  let settingsScope = null;
  try {
    settingsScope = ctx.settings.register(NS, SettingsSchema);
  } catch {
    /* 注册失败时仅用 Config 兜底 */
  }
  // 追踪最近活跃的会话（任何对话活动事件都刷新；用于"当前项目"判定）
  const recentActivity = new Map();
  const activityListener = (session) => {
    try {
      if (session && session.header && session.header.cwd && session.header.origin !== "subagent") {
        recentActivity.set(session.id, Date.now());
      }
    } catch {
      /* 忽略 */
    }
  };
  ctx.on("session/event", activityListener);
  // 初次启用检查（幂等：只对未检查的红点条目动手；结果写入日志）
  void initialAudit(dshHome, log);

  const route = ctx.webServer.register({
    kind: "prefix",
    path: "/api/skill-manager-ytxue",
    handler: async (req, res) => {
      const u = new URL(req.url, "http://localhost");
      const path = u.pathname.replace(/\/+$/, "");
      try {
        if (req.method === "GET" && path === "/api/skill-manager-ytxue/state") {
          // 前端传入当前会话 cwd（切换会话即同步），host 据此只扫描当前项目的 skill
          const explicitCwd = u.searchParams.get("cwd") || "";
          const { roots, currentRoot } = resolveProjectRoots(ctx, config, dshHome, recentActivity, explicitCwd, settingsScope);
          const data = await state(dshHome, { projectRoots: roots, currentRoot });
          json(res, 200, { ok: true, data });
          return;
        }
        if (req.method === "GET" && path === "/api/skill-manager-ytxue/list-dir") {
          run(res, listDir(u.searchParams.get("path") || "").then((r) => ({ ok: true, data: r.data || r })));
          return;
        }
        if (req.method !== "POST") {
          json(res, 405, { ok: false, error: `method not allowed: ${req.method}` });
          return;
        }
        const body = await readBody(req);
        switch (path) {
          case "/api/skill-manager-ytxue/check":
            run(res, initialAudit(dshHome, log).then((r) => ({ ok: true, data: r })));
            return;
          case "/api/skill-manager-ytxue/enable":
            run(res, enableSkill(dshHome, String(body.name || ""), log).then((r) => (r.ok ? { ok: true, data: r } : r)));
            return;
          case "/api/skill-manager-ytxue/disable":
            run(res, disableSkill(dshHome, String(body.name || ""), log).then((r) => (r.ok ? { ok: true, data: r } : r)));
            return;
          case "/api/skill-manager-ytxue/import":
            run(res, importPath(dshHome, String(body.source || ""), log, {
              target: body.target === "skills" ? "skills" : "pool",
              conflict: body.conflict === "overwrite" ? "overwrite" : "skip",
              dryRun: body.dryRun === true,
            }));
            return;
          default:
            json(res, 404, { ok: false, error: `unknown action: ${path}` });
        }
      } catch (e) {
        json(res, 500, { ok: false, error: String(e && e.message ? e.message : e) });
      }
    },
  });
  return route;
}


export { apply, inject, name };
